import{z as n,x as p,o as t,c as A,q as E,j as i,D as s,d as r,s as o,S as l,b as B}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"Dijkstra 在 OSPF","description":"","frontmatter":{"title":"Dijkstra 在 OSPF","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ospf-dijkstra.md","filePath":"cs/ospf-dijkstra.md","lastUpdated":1791063341000}'),d={name:"cs/ospf-dijkstra.md"};function D(F,a,P,k,m,S){const e=p("Mermaid");return t(),A("div",null,[a[2]||(a[2]=E('<h1 id="dijkstra-在-ospf" tabindex="-1">Dijkstra 在 OSPF <a class="header-anchor" href="#dijkstra-在-ospf" aria-label="Permalink to &quot;Dijkstra 在 OSPF&quot;">​</a></h1><div class="epigraph"><p>链路状态库是同一张带权图；每台路由器以自己为源跑 Dijkstra，下一跳才写进 FIB。</p><footer>—— 据 Dijkstra 最短路；Moy, RFC 2328 OSPF Version 2；Kurose and Ross</footer></div><p><a href="/cs/link-state">上一课</a>给出洪泛邻接与「各节点独立计算」。本课不重写 LSA 洪泛可靠性。缺口是计算本身：图课的 <a href="/cs/dijkstra">Dijkstra</a> 已经会单源最短路；这里要接到 OSPF 的代价、区域直觉和「下一跳是邻居而不是整条路径」。本课不把 BGP 政策提前。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>链路状态通告描述「我连谁、代价多少」。若只停在「有一张图」，还不会转发。OSPF：从 LSDB 建图，节点是路由器与网络，边权是接口代价。以本机为源跑 Dijkstra，得到到每个前缀的出口邻居。区域把洪泛范围切开，骨干连通各区域，避免全网一张图过大。缺口是<strong>把最短路树写成转发表</strong>。</p><p><span class="marginnote">直觉类比：Dijkstra 像水波从本机往外漫——代价小的方向先淹到，每个节点第一次被淹到时的深度就是它的最短代价；已经淹过的方向不用再看，这保证了「贪心」在这里不出错。</span></p><p><span class="marginnote">代价常与带宽相关，由管理设定，不是时延测量。ECMP 在多条等代价时分流，仍要求下一跳是邻居。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>同步 LSDB（可靠洪泛、序号）。算 SPF 树。把叶子网络的前缀安装为「下一跳 = 树上来的第一跳邻居」，再交给 <a href="/cs/lpm">LPM</a>。区域内与区域间前缀来源不同，但查找规则仍是最长前缀。本课不把全部 LSA 类型表当必背。</p>',9)),(t(),i(l,null,{default:s(()=>[o(e,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20LSDB%5B%22%E9%93%BE%E8%B7%AF%E7%8A%B6%E6%80%81%E5%BA%93%22%5D%20--%3E%20G%5B%22%E5%B8%A6%E6%9D%83%E5%9B%BE%22%5D%0A%20%20G%20--%3E%20SPF%5B%22%E6%9C%AC%E6%9C%BA%E4%B8%BA%E6%BA%90%E7%9A%84%20Dijkstra%22%5D%0A%20%20SPF%20--%3E%20FIB%5B%22%E4%B8%8B%E4%B8%80%E8%B7%B3%E5%86%99%E5%85%A5%20FIB%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=B("h2",{id:"机制",tabindex:"-1"},[r("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=B("p",null,"每台路由器计算自己的树，但仍应得到相容的转发：同一张无向代价图、同一算法。与距离向量对照：坏消息随拓扑洪泛，不必数到无穷。域内 IGP 仍是一个管理域的最短路；跨域政策不是代价最小，下一课 BGP。",-1)),a[5]||(a[5]=B("p",null,"树变成 FIB 时只记「第一跳」：目的网挂在树上的哪条枝无所谓，转发只看枝根是哪个邻居。沿路的每一台路由器各自这样记一跳，接力起来就是完整路径——路径不写在任何一张表里，而是分散在沿途各台的树里。",-1)),(t(),i(l,null,{default:s(()=>[o(e,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20ROOT%5B%22%E6%9C%AC%E6%9C%BA%EF%BC%88%E6%A0%91%E7%9A%84%E6%A0%B9%EF%BC%89%22%5D%20--%3E%20A%5B%22%E9%82%BB%E5%B1%85%20A%EF%BC%8C%E6%8E%A5%E5%8F%A3%E4%BB%A3%E4%BB%B7%2010%22%5D%0A%20%20ROOT%20--%3E%20B%5B%22%E9%82%BB%E5%B1%85%20B%EF%BC%8C%E6%8E%A5%E5%8F%A3%E4%BB%A3%E4%BB%B7%2020%22%5D%0A%20%20A%20--%3E%20X%5B%22%E7%9B%AE%E7%9A%84%E7%BD%91%20X%EF%BC%9A%E6%80%BB%E4%BB%A3%E4%BB%B7%2025%22%5D%0A%20%20B%20--%3E%20Y%5B%22%E7%9B%AE%E7%9A%84%E7%BD%91%20Y%EF%BC%9A%E6%80%BB%E4%BB%A3%E4%BB%B7%2035%22%5D%0A%20%20X%20--%3E%20NH1%5B%22FIB%EF%BC%9A%E5%8E%BB%20X%20%E8%B5%B0%20A%EF%BC%88%E5%8F%AA%E8%AE%B0%E7%AC%AC%E4%B8%80%E8%B7%B3%EF%BC%89%22%5D%0A%20%20Y%20--%3E%20NH2%5B%22FIB%EF%BC%9A%E5%8E%BB%20Y%20%E8%B5%B0%20B%22%5D%0A"})]),fallback:s(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=E('<p><span class="marginnote">数字实例：接口代价常按参考带宽除以链路带宽设定，参考带宽 100 Mbps 时，一条 100 Mbps 链路代价 1，一条 10 Mbps 链路代价 10；三条 10 Mbps 串起来代价 30，仍输给一条 100 Mbps 的 1——SPF 自动选后者。</span></p><p><span class="marginnote">常见误区：初学者容易以为路由表里存着整条路径。实际每台路由器只存「下一跳是哪个邻居」，包每过一跳由那台路由器接着查表——没有任何一台持有全图，路径是接力出来的。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 IS-IS TLV 细节当第二条主干，不把流量工程的约束最短路写成 OSPF 正文。多区域虚拟链路是例外，不展开。自治系统之间如何交换路径，下一课 BGP 直觉。</p><p>后课默认：一个 AS 内部可以用 Dijkstra 填下一跳。互联网的边界路由换政策语言。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>OSPF 在同步图上跑 Dijkstra，安装邻居下一跳。</li><li>区域缩小洪泛，不改变 LPM。</li><li>跨 AS 不是最短路，下一课 BGP。</li><li>出处：RFC 2328；Dijkstra；Kurose and Ross。</li></ul>',7))])}const h=n(d,[["render",D]]);export{C as __pageData,h as default};
